package com.benjamintaskis.createsignalextensions.network; import com.benjamintaskis.createsignalextensions.CreateSignallingAdditions; import net.minecraft.core.BlockPos; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; public record AdjustSignalVerticalPayload(BlockPos pos,int delta) implements CustomPacketPayload { public static final Type<AdjustSignalVerticalPayload> TYPE=new Type<>(CreateSignallingAdditions.id("adjust_signal_vertical")); public static final StreamCodec<RegistryFriendlyByteBuf,AdjustSignalVerticalPayload> STREAM_CODEC=StreamCodec.ofMember(AdjustSignalVerticalPayload::encode,AdjustSignalVerticalPayload::new); public AdjustSignalVerticalPayload(RegistryFriendlyByteBuf b){this(b.readBlockPos(),b.readVarInt());} private void encode(RegistryFriendlyByteBuf b){b.writeBlockPos(pos);b.writeVarInt(delta);} public Type<? extends CustomPacketPayload> type(){return TYPE;} }